using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Text;
using System.Threading.Tasks;

namespace UserProfileApi
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
            services.AddSingleton<IUserRepository, InMemoryUserRepository>();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints => { endpoints.MapControllers(); });
        }
    }

    public interface IUserRepository
    {
        string GetDisplayName(string userId);
        void SetDisplayName(string userId, string name);
    }

    public class InMemoryUserRepository : IUserRepository
    {
        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, string> _store = new();
        public string GetDisplayName(string userId) => _store.GetValueOrDefault(userId, "Anonymous");
        public void SetDisplayName(string userId, string name) => _store[userId] = name;
    }

    [ApiController]
    [Route("api/[controller]")]
    public class ProfileController : ControllerBase
    {
        private readonly IUserRepository _repo;

        public ProfileController(IUserRepository repo)
        {
            _repo = repo;
        }

        [HttpPost("update")]
        public IActionResult UpdateProfile([FromBody] ProfileUpdateRequest request)
        {
            if (string.IsNullOrEmpty(request?.UserId) || string.IsNullOrEmpty(request?.DisplayName))
                return BadRequest("UserId and DisplayName are required");

            // Basic length validation
            if (request.DisplayName.Length > 128)
                return BadRequest("DisplayName too long");

            _repo.SetDisplayName(request.UserId, request.DisplayName);
            return Ok(new { status = "updated" });
        }

        [HttpGet("card/{userId}")]
        public IActionResult GetProfileCard(string userId)
        {
            var displayName = _repo.GetDisplayName(userId);

            // Generate an HTML profile card using string formatting
            // Developer intended to use a template but used string.Format directly
            var template = @"<!DOCTYPE html>
<html>
<head><title>Profile Card</title></head>
<body>
<div class='profile-card'>
    <h2>User Profile</h2>
    <p class='display-name'>Name: {0}</p>
    <p class='user-id'>ID: {1}</p>
    <p class='generated'>Generated at: {2}</p>
</div>
</body>
</html>";

            // VULNERABILITY: displayName is user-controlled and directly interpolated
            // into HTML without encoding, enabling stored XSS
            var html = string.Format(template, displayName, userId, DateTime.UtcNow.ToString("o"));

            return Content(html, "text/html", Encoding.UTF8);
        }

        [HttpGet("search")]
        public IActionResult SearchProfile([FromQuery] string q)
        {
            // Reflected variant - search query echoed back
            var responseHtml = string.Format(
                "<html><body><h3>Search results for: {0}</h3><p>No results found.</p></body></html>",
                q ?? "");

            return Content(responseHtml, "text/html", Encoding.UTF8);
        }
    }

    public class ProfileUpdateRequest
    {
        public string UserId { get; set; }
        public string DisplayName { get; set; }
    }
}
